face.layout_source:
// arp-2600.face: the panel for tap/examples/synths/poly/arp-2600.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/synths/poly/arp-2600.face --meta <graph>.cragmeta

face "ARP 2600" {
  row(gap = 10) {
    box "VCO 1" { knob "Tune" (vco1_tune) knob "S/H" (vco1_fm_sh) knob "ADSR" (vco1_fm_adsr) knob "VCO 2" (vco1_fm_vco2) }
    box "VCO 2" (grow = 1) {
      knob "Tune" (vco2_tune) knob "Width" (vco2_width) knob "S/H" (vco2_fm_sh) knob "ADSR" (vco2_fm_adsr)
      knob "VCO 1" (vco2_fm_vco1) knob "PWM" (vco2_pwm_noise)
    }
    box "VCO 3" {
      knob "Tune" (vco3_tune) knob "Width" (vco3_width) knob "Noise" (vco3_fm_noise) knob "ADSR" (vco3_fm_adsr)
      knob "VCO 2" (vco3_fm_vco2)
    }
  }
  row(gap = 10) {
    box "Noise / S&H" { knob "Colour" (noise_color) knob "Rate" (sh_rate) knob "Glide" (portamento) }
    box "Mixer" {
      vslider "Ring" (mix_ring) vslider "1" (mix_vco1) vslider "2" (mix_vco2) vslider "3" (mix_vco3)
      vslider "Noise" (mix_noise)
    }
    box "VCF" (grow = 1) {
      knob.big "Cutoff" (cutoff) knob "Res" (resonance) knob "Kbd" (vcf_kbd) knob "ADSR" (vcf_adsr)
      knob "VCO 2" (vcf_vco2)
    }
    box "VCA" { knob "VCF" (vca_vcf) knob "Ring" (vca_ring) knob "AR" (vca_ar) knob "ADSR" (vca_adsr) }
  }
  row(gap = 10) {
    box "ADSR" { adsr(attack, decay, sustain, release) }
    box "AR" { knob "Attack" (ar_attack) knob "Release" (ar_release) }
    box "Output" (grow = 1) { knob "Spread" (pan_spread) knob "Reverb" (reverb) knob.big "Volume" (volume) viz(grow = 1) }
  }
  keys(note_on, note_off)
}
